using System;
using System.Collections.Generic;

// Orders module: only the interface is public to other modules.
public interface IOrdersApi { decimal TotalFor(string customer); }

// Internal details are hidden. In a real solution this class is "internal"
// in its own project, so other modules cannot reference it directly.
class OrdersModule : IOrdersApi
{
    readonly Dictionary<string, List<decimal>> data = new Dictionary<string, List<decimal>>
    {
        ["anna"] = new List<decimal> { 20m, 35.5m },
        ["bob"] = new List<decimal> { 10m }
    };
    public decimal TotalFor(string c)
    {
        decimal sum = 0;
        if (data.TryGetValue(c, out var list)) foreach (var x in list) sum += x;
        return sum;
    }
}

// Billing module depends only on the contract, never on Orders internals.
class BillingModule
{
    readonly IOrdersApi orders;
    public BillingModule(IOrdersApi o) { orders = o; }
    public string Invoice(string c) => $"Invoice for {c}: {orders.TotalFor(c)}";
}

class Program
{
    static void Main()
    {
        // One deployable unit, two modules, one clear seam between them.
        var billing = new BillingModule(new OrdersModule());
        Console.WriteLine(billing.Invoice("anna"));
        Console.WriteLine(billing.Invoice("bob"));
        // Time O(items per customer), space O(1) extra.
    }
}

using System;
using System.Collections.Generic;

// Domain layer: knows nothing about databases. It owns the interface.
public record Order(int Id, decimal Amount);
public interface IOrderRepository { void Save(Order o); IReadOnlyList<Order> All(); }

// Application layer: business rule uses only the interface.
public class PlaceOrder
{
    readonly IOrderRepository repo;
    public PlaceOrder(IOrderRepository r) { repo = r; }
    public string Handle(int id, decimal amount)
    {
        if (amount <= 0) return "rejected: amount must be positive"; // rule lives inward
        repo.Save(new Order(id, amount));
        return "saved order " + id;
    }
}

// Infrastructure layer: depends inward on the interface (arrows point to the domain).
public class InMemoryRepository : IOrderRepository
{
    readonly List<Order> list = new List<Order>();
    public void Save(Order o) { list.Add(o); }
    public IReadOnlyList<Order> All() => list;
}

class Program
{
    static void Main()
    {
        var repo = new InMemoryRepository();          // swap for an EF Core repo in production
        var useCase = new PlaceOrder(repo);
        Console.WriteLine(useCase.Handle(1, 49.90m));
        Console.WriteLine(useCase.Handle(2, -5m));
        Console.WriteLine("stored orders: " + repo.All().Count);
        // Time O(1) per call, space O(n) for stored orders.
    }
}

using System;
using System.Collections.Generic;

record OrderPlaced(Guid EventId, int OrderId); // an event: past tense, many subscribers

class Bus
{
    readonly List<Action<OrderPlaced>> subs = new List<Action<OrderPlaced>>();
    public void Subscribe(Action<OrderPlaced> h) { subs.Add(h); }
    public void Publish(OrderPlaced e) { foreach (var s in subs) s(e); }
}

class Program
{
    static void Main()
    {
        var bus = new Bus();
        var seen = new HashSet<Guid>();   // processed message ids = idempotency
        int emails = 0;

        bus.Subscribe(e => {
            if (!seen.Add(e.EventId)) { Console.WriteLine("duplicate ignored " + e.OrderId); return; }
            emails++; Console.WriteLine("email sent for order " + e.OrderId);
        });
        bus.Subscribe(e => Console.WriteLine("analytics counted order " + e.OrderId));

        var evt = new OrderPlaced(Guid.NewGuid(), 42);
        bus.Publish(evt);
        bus.Publish(evt);  // broker redelivered: at-least-once means this can happen
        Console.WriteLine("emails sent: " + emails);
        // Time O(subscribers) per publish, space O(processed ids).
    }
}

using System;

class Breaker
{
    int failures; DateTime openUntil = DateTime.MinValue;
    public bool Open => DateTime.UtcNow < openUntil;
    public void Fail() { if (++failures >= 3) openUntil = DateTime.UtcNow.AddSeconds(30); }
    public void Ok() { failures = 0; }
}

class Program
{
    static int calls;
    static string FlakyService() { if (++calls < 4) throw new Exception("503"); return "OK on call " + calls; }

    static void Main()
    {
        var rnd = new Random(1);
        var breaker = new Breaker();
        for (int attempt = 1; attempt <= 5; attempt++)
        {
            if (breaker.Open) { Console.WriteLine("circuit open, failing fast"); break; }
            try { Console.WriteLine(FlakyService()); breaker.Ok(); break; }
            catch (Exception e)
            {
                breaker.Fail();
                // exponential backoff: 100, 200, 400 ms ... plus random jitter
                double delay = 100 * Math.Pow(2, attempt - 1) + rnd.Next(0, 50);
                Console.WriteLine($"attempt {attempt} failed ({e.Message}), wait {delay:F0} ms");
            }
        }
        // Time O(attempts), space O(1). Real code would use Polly or Microsoft.Extensions.Resilience.
    }
}

using System;
using System.Collections.Generic;

class Cache
{
    readonly Dictionary<string, (string val, DateTime exp)> store = new Dictionary<string, (string, DateTime)>();
    readonly object gate = new object();
    public int DbCalls;

    string LoadFromDb(string key) { DbCalls++; return "value-of-" + key; } // slow and costly

    public string Get(string key)
    {
        lock (gate)  // one loader at a time: avoids a stampede on a cold key
        {
            if (store.TryGetValue(key, out var e) && e.exp > DateTime.UtcNow) return e.val; // hit
            var v = LoadFromDb(key);                                                          // miss
            store[key] = (v, DateTime.UtcNow.AddSeconds(60));                                 // TTL 60 s
            return v;
        }
    }
}

class Program
{
    static void Main()
    {
        var c = new Cache();
        for (int i = 0; i < 5; i++) Console.WriteLine(c.Get("user:7"));
        Console.WriteLine("5 reads, database calls: " + c.DbCalls);
        // Time O(1) per read, space O(keys). Without the cache: 5 database calls.
    }
}

using System;

class Program
{
    static void Main()
    {
        double usersPerDay = 2_000_000, reqPerUser = 20;
        double secondsPerDay = 100_000;               // rounded from 86,400
        double avgRps = usersPerDay * reqPerUser / secondsPerDay;
        double peakRps = avgRps * 5;                  // peak is often 5-10x average
        double perServerRps = 500;                    // measured or assumed capacity
        double servers = Math.Ceiling(peakRps / perServerRps) + 1; // +1 for failure

        double bookingsPerDay = 200_000, bytesEach = 2_000;
        double gbPerYear = bookingsPerDay * bytesEach * 365 / 1e9;

        Console.WriteLine($"average RPS: {avgRps}");
        Console.WriteLine($"peak RPS:    {peakRps}");
        Console.WriteLine($"servers:     {servers}");
        Console.WriteLine($"storage/year: {gbPerYear:F0} GB");
        // The numbers only steer the design; precision is not the goal.
        // Time and space O(1).
    }
}

using System;

class Program
{
    static void Main()
    {
        double slo = 0.999;                   // objective: 99.9% of requests succeed
        long total = 10_000_000;              // requests this month
        long failed = 6_500;                  // measured failures (the SLI numerator)

        double sli = 1.0 - (double)failed / total;
        long budget = (long)(total * (1 - slo));      // failures we may afford
        double used = (double)failed / budget * 100;

        Console.WriteLine($"SLI measured: {sli:P3}");
        Console.WriteLine($"error budget: {budget} failed requests");
        Console.WriteLine($"budget used:  {used:F0}%");
        Console.WriteLine(used > 100 ? "freeze features, fix reliability" : "room to ship");
        // Time O(1), space O(1).
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static Dictionary<string, string> primary = new Dictionary<string, string>();
    static Dictionary<string, string> replica = new Dictionary<string, string>();
    static Queue<(string k, string v)> replication = new Queue<(string, string)>();

    static void Write(string k, string v) { primary[k] = v; replication.Enqueue((k, v)); }
    static void ReplicateOne() { if (replication.Count > 0) { var (k, v) = replication.Dequeue(); replica[k] = v; } }
    static string Read(Dictionary<string, string> db, string k) => db.TryGetValue(k, out var v) ? v : "(old/empty)";

    static void Main()
    {
        primary["name"] = replica["name"] = "Anna";
        Write("name", "Anne");                                       // user saves
        Console.WriteLine("read replica now:    " + Read(replica, "name")); // stale
        Console.WriteLine("read primary now:    " + Read(primary, "name")); // read-your-writes
        ReplicateOne();                                              // replication catches up
        Console.WriteLine("read replica later:  " + Read(replica, "name"));
        // Eventual consistency: all copies agree once updates stop and replication finishes.
        // Time O(1) per operation, space O(keys).
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        // Each step has an action and a compensation that undoes it.
        var steps = new List<(string name, Func<bool> act, Action undo)>
        {
            ("reserve stock", () => true,  () => Console.WriteLine("  undo: release stock")),
            ("charge card",   () => true,  () => Console.WriteLine("  undo: refund card")),
            ("book shipping", () => false, () => Console.WriteLine("  undo: cancel shipping")) // fails
        };

        var done = new Stack<(string name, Func<bool> act, Action undo)>();
        foreach (var s in steps)
        {
            Console.WriteLine("run: " + s.name);
            if (s.act()) { done.Push(s); continue; }
            Console.WriteLine("failed at: " + s.name + ", compensating");
            while (done.Count > 0) done.Pop().undo();   // reverse order
            Console.WriteLine("saga ended: order cancelled");
            return;
        }
        Console.WriteLine("saga ended: order confirmed");
        // Time O(steps), space O(steps). Real sagas persist their state between steps.
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static List<string> orders = new List<string>();                      // business table
    static List<(Guid id, string payload, bool sent)> outbox = new List<(Guid, string, bool)>(); // outbox table
    static HashSet<Guid> processed = new HashSet<Guid>();                 // consumer's inbox

    static void PlaceOrder(string name)
    {
        // In a real database both inserts are ONE transaction: both happen or neither.
        orders.Add(name);
        outbox.Add((Guid.NewGuid(), "OrderPlaced:" + name, false));
    }

    static void Consume((Guid id, string payload, bool sent) m)
    {
        if (!processed.Add(m.id)) { Console.WriteLine("skip duplicate " + m.payload); return; }
        Console.WriteLine("handled " + m.payload);
    }

    static void Main()
    {
        PlaceOrder("book");
        for (int round = 1; round <= 2; round++)           // publisher runs twice (crash and restart)
            foreach (var m in outbox) Consume(m);          // at-least-once: sends again
        Console.WriteLine("orders: " + orders.Count + ", handled once: " + processed.Count);
        // Time O(messages), space O(messages). "Exactly once" = at-least-once + idempotent handling.
    }
}

using System;
using System.Collections.Generic;

abstract class Event { }
class Deposited : Event { public decimal Amount; }
class Withdrawn : Event { public decimal Amount; }

class Account
{
    public decimal Balance;
    public void Apply(Event e)   // state is only ever changed by applying events
    {
        if (e is Deposited d) Balance += d.Amount;
        else if (e is Withdrawn w) Balance -= w.Amount;
    }
}

class Program
{
    static void Main()
    {
        var log = new List<Event>                       // append-only: the source of truth
        {
            new Deposited { Amount = 100 },
            new Withdrawn { Amount = 30 },
            new Deposited { Amount = 5 }
        };
        var acc = new Account();
        foreach (var e in log) acc.Apply(e);
        Console.WriteLine("events: " + log.Count + ", balance: " + acc.Balance);
        // Balance after the first 2 events (time travel):
        var past = new Account();
        for (int i = 0; i < 2; i++) past.Apply(log[i]);
        Console.WriteLine("balance after 2 events: " + past.Balance);
        // Time O(events); snapshots make replay faster. Space O(events).
    }
}

using System;
using System.Collections.Generic;
using System.Linq;

record Invoice(int Id, string TenantId, decimal Amount);

class TenantContext { public string TenantId = ""; }

class InvoiceRepo
{
    readonly List<Invoice> table = new List<Invoice>
    {
        new Invoice(1, "acme", 100), new Invoice(2, "acme", 40), new Invoice(3, "globex", 999)
    };
    readonly TenantContext ctx;
    public InvoiceRepo(TenantContext c) { ctx = c; }

    // Like an EF Core global query filter: every query is scoped automatically.
    public IEnumerable<Invoice> Query() => table.Where(i => i.TenantId == ctx.TenantId);
    // A developer who forgets the filter would leak data, so isolation must be automatic.
    public IEnumerable<Invoice> UnsafeAll() => table;
}

class Program
{
    static void Main()
    {
        var ctx = new TenantContext { TenantId = "acme" };   // from the validated token
        var repo = new InvoiceRepo(ctx);
        Console.WriteLine("acme sees: " + string.Join(", ", repo.Query().Select(i => i.Id)));
        ctx.TenantId = "globex";
        Console.WriteLine("globex sees: " + string.Join(", ", repo.Query().Select(i => i.Id)));
        Console.WriteLine("unfiltered (bug): " + repo.UnsafeAll().Count() + " rows");
        // Time O(rows) here (a database uses an index on TenantId), space O(1).
    }
}

using System;
using System.Collections.Generic;

class OrderLine { public string Sku = ""; public int Qty; public decimal Price; }

// Aggregate root: the only door into the order; it protects the rules.
class Order
{
    readonly List<OrderLine> lines = new List<OrderLine>();
    const int MaxLines = 3;
    public bool Submitted { get; private set; }

    public void AddLine(string sku, int qty, decimal price)
    {
        if (Submitted) throw new InvalidOperationException("order already submitted");
        if (qty <= 0) throw new ArgumentException("qty must be positive");
        if (lines.Count >= MaxLines) throw new InvalidOperationException("max 3 lines");
        lines.Add(new OrderLine { Sku = sku, Qty = qty, Price = price });
    }
    public void Submit() { if (lines.Count == 0) throw new InvalidOperationException("empty order"); Submitted = true; }
    public decimal Total() { decimal t = 0; foreach (var l in lines) t += l.Qty * l.Price; return t; }
}

class Program
{
    static void Main()
    {
        var o = new Order();
        o.AddLine("A1", 2, 10m); o.AddLine("B2", 1, 4.5m);
        o.Submit();
        Console.WriteLine("total: " + o.Total());
        try { o.AddLine("C3", 1, 1m); } catch (Exception e) { Console.WriteLine("blocked: " + e.Message); }
        // Time O(lines), space O(lines).
    }
}

using System;

class Program
{
    static void Main()
    {
        double minutesPer30Days = 30 * 24 * 60;
        foreach (double target in new[] { 0.99, 0.999, 0.9999 })
            Console.WriteLine($"{target:P2} -> {minutesPer30Days * (1 - target):F1} min downtime per 30 days");

        // Services in a chain multiply: the result is lower than the weakest one.
        double[] chain = { 0.9995, 0.9995, 0.999 };   // gateway, app, database
        double combined = 1;
        foreach (var a in chain) combined *= a;
        Console.WriteLine($"chain of 3 services: {combined:P3}");
        // Redundancy (2 copies in parallel): 1 - (1-a)^2
        double parallel = 1 - Math.Pow(1 - 0.999, 2);
        Console.WriteLine($"two 99.9% copies in parallel: {parallel:P4}");
        // Time O(1), space O(1).
    }
}

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;

class Program
{
    static int dbCalls;
    static Dictionary<int, List<string>> itemsByOrder = Enumerable.Range(1, 500)
        .ToDictionary(i => i, i => new List<string> { "a" + i, "b" + i });

    // Each call simulates a database round trip (~1 ms in real life).
    static List<string> ItemsForOrder(int id) { dbCalls++; return itemsByOrder[id]; }
    static Dictionary<int, List<string>> ItemsForOrders(int[] ids)
    { dbCalls++; return ids.ToDictionary(i => i, i => itemsByOrder[i]); }

    static void Main()
    {
        int[] orderIds = Enumerable.Range(1, 500).ToArray();

        dbCalls = 0; int n1 = 0;
        foreach (var id in orderIds) n1 += ItemsForOrder(id).Count;       // N+1 pattern
        Console.WriteLine($"N+1:     {n1} items, {dbCalls} database calls");

        dbCalls = 0;
        int batched = ItemsForOrders(orderIds).Values.Sum(l => l.Count);  // one query with IN (...)
        Console.WriteLine($"batched: {batched} items, {dbCalls} database call");
        // At 1 ms per call: about 500 ms against about 1 ms. Time O(N) both here, round trips O(N) vs O(1).
    }
}

using System;

class Program
{
    static void Main()
    {
        // (name, optimistic, most likely, pessimistic) in days
        var tasks = new[]
        {
            ("API endpoints",   3.0, 5.0, 9.0),
            ("Database change", 1.0, 2.0, 5.0),
            ("Tests + review",  2.0, 3.0, 5.0),
        };
        double totalExpected = 0, totalVar = 0;
        foreach (var (name, o, m, p) in tasks)
        {
            double e = (o + 4 * m + p) / 6;      // PERT weighted average
            double sd = (p - o) / 6;             // spread of the guess
            totalExpected += e; totalVar += sd * sd;
            Console.WriteLine($"{name,-16} expected {e:F1} d (+/- {sd:F1})");
        }
        double total = Math.Round(totalExpected, 1), sdTotal = Math.Sqrt(totalVar);
        Console.WriteLine($"total: {total} days, likely range {total - sdTotal * 2:F1} to {total + sdTotal * 2:F1} days");
        // Time O(tasks), space O(1). Give the range, not one number.
    }
}
